<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/auth.php';require_once __DIR__.'/../config/helpers.php';requireRole('admin');$base='..';$assetBase='../assets';$pageTitle='Monitor Absensi';require __DIR__.'/../partials/head.php'; ?><div class="dashboard-layout"><?php require __DIR__.'/../partials/sidebar.php'; ?><main class="main"><div class="mobile-head"><b>Sistem Absensi QR</b><button class="menu-toggle">☰</button></div><header class="topbar"><div><h1>Monitor Absensi</h1><p>Pantau catatan kehadiran lintas kelas dan sesi.</p></div><div class="top-actions"><a class="btn btn-ghost" href="../index.php">↗ Beranda</a></div></header>
<?php $rows=$pdo->query("SELECT a.*,m.npm,m.nama,s.tanggal,mk.nama_mk,k.nama_kelas,l.nama_lokasi FROM absensi a JOIN mahasiswa m ON m.id=a.mahasiswa_id JOIN sesi_absensi s ON s.id=a.sesi_id JOIN jadwal j ON j.id=s.jadwal_id JOIN mata_kuliah mk ON mk.id=j.mata_kuliah_id JOIN kelas k ON k.id=j.kelas_id LEFT JOIN lokasi_kampus l ON l.id=a.id ORDER BY a.waktu_absen DESC LIMIT 250")->fetchAll();$hadir=$pdo->query("SELECT COUNT(*) FROM absensi WHERE status IN ('Hadir','Terlambat')")->fetchColumn();$terlambat=$pdo->query("SELECT COUNT(*) FROM absensi WHERE status='Terlambat'")->fetchColumn();?><div class="stats"><div class="stat"><small>Total catatan</small><strong><?=count($rows)?></strong><span>maks. 250 terbaru</span></div><div class="stat"><small>Hadir</small><strong><?=$hadir?></strong><span>seluruh sistem</span></div><div class="stat"><small>Terlambat</small><strong><?=$terlambat?></strong><span>tercatat</span></div><div class="stat"><small>Validasi</small><strong>GPS</strong><span>radius server</span></div></div><section class="section" style="margin-top:20px"><div class="table-wrap"><table class="table"><thead><tr><th>Waktu</th><th>Mahasiswa</th><th>Mata Kuliah</th><th>Kelas</th><th>Status</th><th>Lokasi</th><th>Jarak</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['waktu_absen']??'-')?></td><td><?=e($r['nama'])?><small style="display:block;color:#887d90"><?=e($r['npm'])?></small></td><td><?=e($r['nama_mk'])?></td><td><?=e($r['nama_kelas'])?></td><td><span class="badge green"><?=e($r['status'])?></span></td><td><?=e($r['nama_lokasi']??'-')?></td><td><?=round((float)$r['jarak'])?> m</td></tr><?php endforeach;?></tbody></table></div></section>
</main></div><?php require __DIR__.'/../partials/footer.php'; ?>